#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    int n = (int)s.size();
    vector<vector<int>> t(n + 1, vector<int>(n + 1, 0));
    for (int length = 1; length <= n; length++) {
        for (int i = 0; i + length - 1 < n; i++) {
            int j = i + length - 1;
            int best = 1 + (i < j ? t[i + 1][j] : 0);
            for (int k = i + 1; k <= j; k++) {
                if (s[k] == s[i]) {
                    int v = (i + 1 <= k - 1 ? t[i + 1][k - 1] : 0) + t[k][j];
                    best = min(best, v);
                }
            }
            t[i][j] = best;
        }
    }
    cout << t[0][n - 1] << "\n";

    return 0;
}

